argv:
$ErrorActionPreference='Stop'
$b='http://127.0.0.1:17448'
$a=Invoke-RestMethod -Uri ($b+'/api/supervisor-watchdog/agent-assignments') -TimeoutSec 12
$t=@($a.assignments|Where-Object {$_.id -eq '9f434c35-9e28-4807-8d5f-18569e8bdcf5'})
if($t.Count -ne 1){throw 'ORIGINAL_ASSIGNMENT_MISSING'}
$t=$t[0]
foreach($k in @('state','dispatchCount','dispatchSubmitAttempted','lastPreflightReason','lastDiagnostic','currentHead','ciRunId','ciConclusion','evidenceCollectorStatus','evidenceCollectorError','completedAt','blockedAt','failedAt','evidenceDeadlineAt')){
 $v=$t.$k
 if($k -eq 'evidenceCollectorError' -or $k -eq 'lastDiagnostic'){$v=([string]$v).Substring(0,[math]::Min(210,([string]$v).Length))}
 Write-Output ($k+'='+[string]$v)
}
Write-Output ('OTHER_ACTIVE='+@($a.assignments|Where-Object {$_.id -ne $t.id -and $_.state -in @('queued','dispatching','running','awaiting_evidence','unknown')}).Count)
